import random
from itertools import product

def check_r(r, S):
    P1 = set()
    for f in S:
        for g in S:
            P1.add(f - g)

    P2 = set()
    for p in P1:
        for q in P1:
            P2.add(3 * p * q * r)

    P3 = set()
    # This might be too slow if P1 is large.
    # P3 = {x**2 + y**2 - z**2 - w**2 for x, y, z, w in P1}
    # We can optimize P3 calculation.
    squares = {x**2 for x in P1}
    sums_of_two_squares = {s1 + s2 for s1 in squares for s2 in squares}
    P3 = {s1 - s2 for s1 in sums_of_two_squares for s2 in sums_of_two_squares}

    for val in P2:
        # Use a small epsilon for floating point comparison
        found = False
        for p3_val in P3:
            if abs(val - p3_val) < 1e-9:
                found = True
                break
        if not found:
            return False, val
    return True, None

def test_candidates():
    candidates = [0, 2/3, -2/3, 1/3, -1/3]
    # Use a small S first to narrow down
    for r in candidates:
        is_ok = True
        for _ in range(10):
            S = [random.uniform(-100, 100) for _ in range(10)] # Use size 10 first
            ok, val = check_r(r, S)
            if not ok:
                is_ok = False
                break
        print(f"r = {r}, ok = {is_ok}")

test_candidates()

